<?php
declare(strict_types=1);
require dirname(__DIR__, 2).'/espocrm/bootstrap.php';
use Espo\Core\{Application, AclManager, InjectableFactory};
use Espo\Core\ORM\EntityManager;
use Espo\Core\Tenant\{TenantContext, TenantContextStore};
use Espo\Core\Exceptions\{BadRequest, Conflict, Forbidden, NotFound};
use Espo\Custom\Tools\Conversation\ConversationService;

$app = new Application(); $app->setupSystemUser(); $c = $app->getContainer();
$em = $c->getByClass(EntityManager::class); $factory = $c->getByClass(InjectableFactory::class);
$contexts = $c->getByClass(TenantContextStore::class); $checks = 0;
$a = new TenantContext('30000000-0000-4000-8000-000000000001', 'isolation-alpha', 'conversation-test');
$b = new TenantContext('30000000-0000-4000-8000-000000000002', 'isolation-beta', 'conversation-test');
$assert = function (bool $value, string $message) use (&$checks): void { $checks++; if (!$value) throw new RuntimeException($message); };
$deny = function (callable $fn, string $message) use ($assert): void { $blocked = false; try { $fn(); } catch (BadRequest|Conflict|Forbidden|NotFound $e) { $blocked = true; } $assert($blocked, $message); };
$call = fn ($fn) => $contexts->runWith($a, $fn); $other = fn ($fn) => $contexts->runWith($b, $fn);
$tx = $em->getTransactionManager(); $tx->start();
try {
    $suffix = bin2hex(random_bytes(5));
    $makeUser = fn ($ctx, $type) => $contexts->runWith($ctx, fn () => $em->createEntity('User', ['userName' => 'inbox-'.$type.'-'.$ctx->slug.'-'.$suffix, 'lastName' => $type.' '.$suffix, 'emailAddress' => 'inbox-'.$type.'-'.$ctx->slug.'-'.$suffix.'@example.test', 'type' => $type, 'isActive' => true]));
    $admin = $makeUser($a, 'admin'); $foreign = $makeUser($b, 'admin'); $staff = $makeUser($a, 'regular');
    $admin = $call(fn () => $em->getEntityById('User', $admin->getId()));
    $staff = $call(fn () => $em->getEntityById('User', $staff->getId()));
    $foreign = $other(fn () => $em->getEntityById('User', $foreign->getId()));
    $build = fn ($u) => $factory->createWith(ConversationService::class, ['user' => $u, 'acl' => $c->getByClass(AclManager::class)->createUserAcl($u)]);
    $service = $build($admin); $foreignService = $build($foreign); $regular = $build($staff);
    $mailbox = $call(fn () => $em->createEntity('InboundEmail', ['name' => 'Synthetic shared inbox', 'emailAddress' => 'shared-'.$suffix.'@example.test', 'status' => 'Inactive']));
    $root = $call(fn () => $em->createEntity('Email', ['name' => 'Conversation '.$suffix, 'status' => 'Archived', 'body' => '<p>Hello <strong>team</strong></p>', 'isHtml' => true, 'dateSent' => '2026-10-15 09:00:00', 'assignedUserId' => $admin->getId()]));
    $call(fn () => $em->getRDBRepository('Email')->getRelation($root, 'inboundEmails')->relate($mailbox));
    $personal = $call(fn () => $em->createEntity('Email', ['name' => 'Private '.$suffix, 'status' => 'Archived']));
    $reply = $call(fn () => $em->createEntity('Email', ['name' => 'Re: Conversation '.$suffix, 'status' => 'Archived', 'body' => 'Response', 'repliedId' => $root->getId(), 'dateSent' => '2026-10-15 09:01:00']));
    $call(fn () => $em->getRDBRepository('InboundEmail')->getRelation($mailbox, 'emails')->relate($reply));
    $legacyVersion = $em->getPDO()->prepare('UPDATE email SET version_number=NULL WHERE id=? AND tenant_id=? AND service_id=?');
    $legacyVersion->execute([$root->getId(), $a->tenantId, $a->serviceId]);
    $found = $call(fn () => $service->listing($suffix));
    $assert(array_column($found['list'], 'id') === [$root->getId()], 'Only group-mail roots appear, not personal emails or duplicate replies.');
    $thread = $call(fn () => $service->thread($reply->getId()));
    $assert($thread['conversation']['versionNumber'] === 0, 'Pre-migration emails without a version remain readable and use a zero baseline.');
    $assert($thread['conversation']['id'] === $root->getId() && count($thread['messages']) === 2, 'Native reply links resolve a single chronological thread.');
    $assert(str_contains($thread['messages'][0]['bodyPlain'], 'Hello'), 'Native body is available without storing a second copy.');
    $deny(fn () => $call(fn () => $service->thread($personal->getId())), 'Personal-only mail cannot enter the shared inbox by guessed ID.');
    $deny(fn () => $other(fn () => $foreignService->thread($root->getId())), 'Cross-tenant threads are unavailable.');
    $deny(fn () => $call(fn () => $regular->listing()), 'Unprivileged staff cannot bypass native email permissions.');
    $role = $call(fn () => $em->createEntity('Role', [
        'name' => 'Inbox read only '.$suffix,
        'data' => ['Email' => ['read' => 'all', 'edit' => 'no', 'create' => 'no', 'delete' => 'no']],
        'fieldData' => ['Email' => ['body' => ['read' => 'no', 'edit' => 'no']]],
    ]));
    $reader = $call(fn () => $em->createEntity('User', ['userName' => 'inbox-reader-'.$suffix, 'emailAddress' => 'inbox-reader-'.$suffix.'@example.test', 'type' => 'regular', 'isActive' => true]));
    $call(fn () => $em->getRDBRepository('User')->getRelation($reader, 'roles')->relate($role));
    $reader = $call(fn () => $em->getEntityById('User', $reader->getId())); $readOnly = $build($reader);
    $limited = $call(fn () => $readOnly->thread($root->getId()));
    $assert(count($limited['messages']) === 2 && $limited['messages'][0]['bodyPlain'] === '' && !$limited['messages'][0]['canReply'], 'Read-only staff can see permitted threads without hidden bodies or reply capability.');
    $assert(!$limited['canEdit'] && !$limited['canAssign'], 'Read-only staff receive disabled management controls.');
    $version = $thread['conversation']['versionNumber'];
    $deny(fn () => $call(fn () => $readOnly->update($root->getId(), (object) ['conversationStatus' => 'Closed', 'assignedUserId' => null, 'expectedStatus' => 'Open', 'expectedOwnerId' => $admin->getId(), 'expectedVersion' => $version])), 'Direct API calls cannot bypass read-only email roles.');
    $input = (object) ['conversationStatus' => 'Pending', 'assignedUserId' => $staff->getId(), 'expectedStatus' => 'Open', 'expectedOwnerId' => $admin->getId(), 'expectedVersion' => $version];
    $saved = $call(fn () => $service->update($root->getId(), $input));
    $assert($saved['conversation']['conversationStatus'] === 'Pending' && $saved['conversation']['assignedUserId'] === $staff->getId(), 'Triage uses native ownership and independent conversation state.');
    $native = $call(fn () => $em->getEntityById('Email', $root->getId()));
    $assert($native->get('status') === 'Archived', 'Conversation updates cannot alter native transport status.');
    $deny(fn () => $call(fn () => $service->update($root->getId(), $input)), 'A stale assignment cannot overwrite newer triage.');
    $foreignInput = (object) ['conversationStatus' => 'Closed', 'assignedUserId' => $foreign->getId(), 'expectedStatus' => 'Pending', 'expectedOwnerId' => $staff->getId(), 'expectedVersion' => $saved['conversation']['versionNumber']];
    $deny(fn () => $call(fn () => $service->update($root->getId(), $foreignInput)), 'Foreign staff cannot receive a shared conversation.');
    $assert($call(fn () => $service->thread($root->getId()))['conversation']['conversationStatus'] === 'Pending', 'Failed assignment rolls back its entire update.');
    $assert(count($call(fn () => $service->listing($suffix, '', 'Closed'))['list']) === 0, 'Inbox status filter uses current native values.');
    $assert(count($call(fn () => $service->listing($suffix, '', '', 'mine'))['list']) === 0, 'Assigned-to-me follows the logged-in user, not tenant fixtures.');
    $owners = $call(fn () => $service->owners('regular '.$suffix));
    $assert(in_array($staff->getId(), array_column($owners['list'], 'id'), true) && !in_array($foreign->getId(), array_column($owners['list'], 'id'), true), 'Live owner search is tenant/service scoped.');
    $assert($call(fn () => $service->markRead($root->getId()))['success'], 'Read receipt reuses the native per-user inbox service.');
    $wrong = new TenantContext($a->tenantId, $a->slug, 'wrong-service', '', '20000000-0000-4000-8000-000000000002');
    $deny(fn () => $contexts->runWith($wrong, fn () => $service->thread($root->getId())), 'A tenant identity cannot cross its service boundary.');
    $q = $em->getPDO()->prepare("SELECT actor_user_id,metadata_json FROM nexa_audit_event WHERE subject_id=? AND action='conversation.updated'"); $q->execute([$root->getId()]); $audit = $q->fetch(PDO::FETCH_ASSOC);
    $assert($audit && $audit['actor_user_id'] === $admin->getId() && !str_contains($audit['metadata_json'], 'Hello'), 'Immutable audit records actor and state, not message bodies.');
    $assert($saved['conversation']['versionNumber'] > $version, 'Native Email versions increment when triage is updated.');
    $stale = $saved['conversation'];
    $native = $call(fn () => $em->getEntityById('Email', $root->getId()));
    $native->set('name', 'Conversation edited '.$suffix); $call(fn () => $em->saveEntity($native));
    $deny(fn () => $call(fn () => $service->update($root->getId(), (object) ['conversationStatus' => 'Closed', 'assignedUserId' => $staff->getId(), 'expectedStatus' => 'Pending', 'expectedOwnerId' => $staff->getId(), 'expectedVersion' => $stale['versionNumber']])), 'Native edits invalidate stale inbox versions even when owner and status are unchanged.');
    $fresh = $call(fn () => $service->thread($root->getId()))['conversation'];
    $close = (object) ['conversationStatus' => 'Closed', 'assignedUserId' => $staff->getId(), 'expectedStatus' => 'Pending', 'expectedOwnerId' => $staff->getId(), 'expectedVersion' => $fresh['versionNumber']];
    $closed = $call(fn () => $service->update($root->getId(), $close));
    $incoming = $call(fn () => $em->createEntity('Email', ['name' => 'Customer reply', 'status' => 'Archived', 'repliedId' => $root->getId(), 'body' => 'Thank you'], ['isBeingImported' => true]));
    $assert($call(fn () => $service->thread($root->getId()))['conversation']['conversationStatus'] === 'Closed', 'Import save alone cannot reopen a thread before the actual shared-mailbox association.');
    $call(fn () => $em->getRDBRepository('InboundEmail')->getRelation($mailbox, 'emails')->relate($incoming));
    $reopened = $call(fn () => $service->thread($root->getId()));
    $assert($reopened['conversation']['conversationStatus'] === 'Open' && $reopened['conversation']['versionNumber'] > $closed['conversation']['versionNumber'], 'A trusted native imported customer reply reopens the conversation and invalidates old versions.');
    $deny(fn () => $call(fn () => $service->update($root->getId(), (object) ['conversationStatus' => 'Closed', 'assignedUserId' => $staff->getId(), 'expectedStatus' => 'Open', 'expectedOwnerId' => $staff->getId(), 'expectedVersion' => $closed['conversation']['versionNumber']])), 'Incoming replies cannot be silently closed by stale staff tabs.');
    $call(fn () => $em->getRDBRepository('Email')->getRelation($incoming, 'users')->relate($admin, ['isRead' => false]));
    $assert($call(fn () => $service->thread($root->getId()))['conversation']['isUnread'], 'An unread native descendant makes the thread unread for its recipient.');
    $assert(count($call(fn () => $service->listing($suffix, '', '', '', 'unread'))['list']) === 1, 'Unread view follows recipient-specific native state.');
    $call(fn () => $service->markRead($root->getId()));
    $assert(!$call(fn () => $service->thread($root->getId()))['conversation']['isUnread'], 'Opening a thread marks only current-user native rows as read.');
    $call(fn () => $service->markRead($root->getId(), false));
    $assert($call(fn () => $service->thread($root->getId()))['conversation']['isUnread'], 'Mark unread reuses native read state.');
    $outgoing = $call(fn () => $em->createEntity('Email', ['name' => 'Staff reply', 'status' => 'Sent', 'repliedId' => $root->getId()]));
    $assert(count($call(fn () => $service->listing($suffix, '', '', '', 'replied'))['list']) === 1, 'Replied view requires a readable sent descendant, not another incoming message.');
    $account = $call(fn () => $em->createEntity('Account', ['name' => 'Related company '.$suffix]));
    $native = $call(fn () => $em->getEntityById('Email', $root->getId())); $native->set(['parentType' => 'Account', 'parentId' => $account->getId()]); $call(fn () => $em->saveEntity($native));
    $assert($call(fn () => $service->thread($root->getId()))['context']['id'] === $account->getId(), 'Commercial context reuses a permitted native parent.');
    $assert($call(fn () => $readOnly->thread($root->getId()))['context'] === null, 'Unreadable commercial context is not exposed to email-only roles.');
    $native = $call(fn () => $em->getEntityById('Email', $root->getId())); $native->set('conversationStatus', 'Closed'); $call(fn () => $em->saveEntity($native));
    $call(fn () => $em->createEntity('Email', ['name' => 'Sent from staff', 'status' => 'Sent', 'repliedId' => $root->getId()]));
    $assert($call(fn () => $service->thread($root->getId()))['conversation']['conversationStatus'] === 'Closed', 'Sending a staff reply does not reopen a closed conversation.');
    $call(fn () => $em->createEntity('Email', ['name' => 'Manual archive', 'status' => 'Archived', 'isBeingImported' => true, 'repliedId' => $root->getId()]));
    $assert($call(fn () => $service->thread($root->getId()))['conversation']['conversationStatus'] === 'Closed', 'An editable entity flag cannot impersonate the trusted import save option.');
    $incoming = $call(fn () => $em->getEntityById('Email', $incoming->getId())); $incoming->set('body', 'Existing message edited'); $call(fn () => $em->saveEntity($incoming, ['isBeingImported' => true]));
    $assert($call(fn () => $service->thread($root->getId()))['conversation']['conversationStatus'] === 'Closed', 'Duplicate import processing and message edits cannot reopen a conversation again.');
    $large = $em->getPDO()->prepare("INSERT INTO email (id,tenant_id,service_id,name,status,replied_id,deleted) VALUES (?,?,?,'Synthetic large-thread message','Sent',?,0)");
    for ($index = 0; $index < 201; $index++) $large->execute(['limit'.bin2hex(random_bytes(6)), $a->tenantId, $a->serviceId, $root->getId()]);
    $largeList = $call(fn () => $service->listing($suffix));
    $assert(count($largeList['list']) === 1 && $largeList['list'][0]['threadLimitReached'], 'An oversized thread remains discoverable without breaking the inbox.');
    $assert($largeList['list'][0]['isUnread'] === null, 'Partial traversal cannot falsely claim that a large thread is read.');
    $deny(fn () => $call(fn () => $service->thread($root->getId())), 'The thread API enforces the bounded message limit and directs users to native Email.');
    echo "Conversation checks passed: $checks (rollback-only).\n";
} catch (Throwable $error) { fwrite(STDERR, get_class($error).': '.$error->getMessage()."\n".$error->getTraceAsString()."\n"); throw $error; }
finally { if ($tx->isStarted()) $tx->rollback(); }
